def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    out = [row[:] for row in grid]

    # Keep the substantial colored shapes; their bounding boxes can contain
    # a few stray pixels of another color.
    comps = []
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx))
                        stack.append((ny,nx))
            if len(cells) >= 4:
                comps.append((color, cells))

    # Background noise is removed; pixels inside a substantial object's
    # bounding rectangle are restored to that object's color.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                out[r][c] = bg
    for color, cells in comps:
        rs = [p[0] for p in cells]
        cs = [p[1] for p in cells]
        for r in range(min(rs), max(rs)+1):
            for c in range(min(cs), max(cs)+1):
                if grid[r][c] != bg:
                    out[r][c] = color
    return out
